document.querySelector('#wide').onclick=()=>preset();document.querySelector('#close').onclick=()=>preset(true);document.querySelector('#reset').onclick=()=>{auto=false;document.querySelector('#spin').classList.remove('active');document.querySelector('#spin').setAttribute('aria-pressed','false');preset();};document.querySelector('#spin').onclick=e=>{auto=!auto;e.currentTarget.classList.toggle('active',auto);e.currentTarget.setAttribute('aria-pressed',String(auto));};document.querySelector('#light').onclick=e=>{night=!night;document.body.classList.toggle('night',night);e.currentTarget.textContent=night?'☾ 黃昏':'☀ 午後';scene.background.set(night?'#748a8b':'#e8eadb');scene.fog.color.copy(scene.background);backdrop.material.color.copy(scene.background);hemi.intensity=night?1:2.1;hemi.color.set(night?'#a7bbd3':'#f8f3dc');sun.intensity=night?1.6:3.5;sun.color.set(night?'#ffba7b':'#ffe2ad');sun.position.set(night?-13:-9,night?7:16,10);lanternMat.emissiveIntensity=night?2:.25;lamp.intensity=night?5:0;glass.emissive.set(night?'#e9ad62':'#000000');glass.emissiveIntensity=night?.65:0;renderer.toneMappingExposure=night?1.05:1.15;};
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;if(indoor){interior.update(dt,now/1000);updateQuestHUD();renderer.render(interior.scene,camera);return;}if(transition){let t=Math.min((now-transition.start)/900,1),s=t*t*(3-2*t),f=transition.from,to=transition.to;theta=T.MathUtils.lerp(f.theta,to.theta,s);phi=T.MathUtils.lerp(f.phi,to.phi,s);distance=T.MathUtils.lerp(f.distance,to.distance,s);target.lerpVectors(f.target,to.target,s);if(t===1)transition=null;}if(auto&&pointers.size===0)theta+=dt*.12;updateCamera();const time=now/1000;smoke.forEach((o,i)=>{let t=(time*.22+i/6)%1;o.position.set(hx-1.2+t*.6,6.95+t*2.1,hz-.7+Math.sin(t*4)*.12);o.scale.setScalar(.12+t*.4);});butterflies.forEach((g,i)=>{let t=time*.45+i*2;g.position.set(Math.sin(t)*2.5-2,1.1+Math.sin(time+i)*.25,Math.cos(t*.8)*2+3);g.rotation.y=-t;g.children[0].rotation.y=Math.sin(time*11+i)*.9;g.children[1].rotation.y=-Math.sin(time*11+i)*.9;});water.material.color.setHSL(.49,.2,.49+Math.sin(time*.8)*.018);renderer.render(scene,camera);}
updateCamera();renderer.render(scene,camera);document.querySelector('#loading').style.opacity='0';setTimeout(()=>document.querySelector('#loading')?.remove(),650);requestAnimationFrame(animate);
window.__artStudy={scene,renderer,camera,batches:batches.size};

function showObservation(message){document.querySelector('#observation-text').textContent=message;document.querySelector('#observation').hidden=false;}
function updateSize(){document.querySelector('#size').textContent=interior.small?'✧ 恢復大小':'✧ 縮小';document.querySelector('#mode-label').textContent=(interior.room==='greenhouse'?'溫室':'客廳')+' · '+(interior.small?'迷你 1 : 8':'正常大小');document.querySelector('#size').classList.toggle('active',interior.small);}
function enterHouse(){if(!interior)interior=createInterior(camera);indoor=true;pointers.clear();interior.enter();document.body.classList.add('indoor');document.body.classList.remove('night');document.querySelector('h1').textContent='小屋大冒險';document.querySelector('.subtitle').textContent='尋找三個微小零件，喚醒恢復裝置。';document.querySelector('.hint').textContent='拖曳看四周 · 方向鍵走動 · 電腦 WASD · E 觀察';renderer.toneMappingExposure=1.02;updateSize();document.querySelector('#observation').hidden=true;window.__artStudy.interior=interior;updateQuestHUD();}
function leaveHouse(){indoor=false;pointers.clear();interior.keys.clear();document.body.classList.remove('indoor');document.body.classList.toggle('night',night);document.querySelector('h1').textContent='苔光小院';document.querySelector('.subtitle').textContent='推開門，發現藏在小地方的大世界。';document.querySelector('.hint').textContent='單指拖曳旋轉 · 雙指縮放 · 電腦滾輪拉近';document.querySelector('#mode-label').textContent='庭院 · 第二版';document.querySelector('#observation').hidden=true;camera.fov=36;camera.near=.1;camera.updateProjectionMatrix();renderer.toneMappingExposure=night?1.05:1.15;preset();}
document.querySelector('#enter').onclick=enterHouse;document.querySelector('#exit').onclick=leaveHouse;document.querySelector('#size').onclick=()=>{interior.setSmall(!interior.small);updateSize();document.querySelector('#observation').hidden=true;};document.querySelector('#tour').onclick=()=>{const name=interior.tour();document.querySelector('.subtitle').textContent=name+' · '+(interior.small?'迷你視角':'正常視角');document.querySelector('#observation').hidden=true;};document.querySelector('#inspect').onclick=()=>showObservation(interior.inspect());document.querySelector('#dismiss').onclick=()=>document.querySelector('#observation').hidden=true;
const keyMap={w:'forward',ArrowUp:'forward',s:'back',ArrowDown:'back',a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right'};
addEventListener('keydown',e=>{if(!indoor)return;const k=keyMap[e.key]||keyMap[e.key.toLowerCase()];if(k){e.preventDefault();interior.keys.add(k);}if(e.key.toLowerCase()==='e'&&!e.repeat)showObservation(interior.inspect());});addEventListener('keyup',e=>{const k=keyMap[e.key]||keyMap[e.key.toLowerCase()];if(k&&interior)interior.keys.delete(k);});addEventListener('blur',()=>{pointers.clear();interior?.keys.clear();});
for(const button of document.querySelectorAll('[data-move]')){button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(indoor)interior.keys.add(button.dataset.move);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,()=>interior?.keys.delete(button.dataset.move));}
// Clicking the front door is an alternative to the accessible entry button.
const doorRay=new T.Raycaster();let press=null;root.addEventListener('pointerdown',e=>{press={x:e.clientX,y:e.clientY,time:performance.now()};});root.addEventListener('pointerup',e=>{if(indoor||!press||performance.now()-press.time>450||Math.hypot(e.clientX-press.x,e.clientY-press.y)>7)return;doorRay.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2),camera);scene.updateMatrixWorld(true);if(doorRay.intersectObject(door).length)enterHouse();press=null;});

let hudSignature='';
function updateQuestHUD(){if(!interior)return;const state=interior.quests.state,c=interior.nearby(),signature=JSON.stringify([state,c?.id,c?.label,interior.small,interior.room,journal.count]);if(signature===hudSignature)return;hudSignature=signature;updateSize();ambience.setRoom(interior.room);const names=['小齒輪','光晶','彈簧'];document.querySelector('#quest-progress').textContent=interior.room==='greenhouse'?`溫室發現 ${journal.entries.filter(x=>x.area==='溫室'&&x.found).length} / 5`:state.complete?'恢復裝置已啟動':`微小零件 ${state.parts.filter(Boolean).length} / 3`;document.querySelector('#inventory').textContent=interior.room==='greenhouse'?'沿步道近看葉片、露珠與花朵':names.map((n,i)=>(state.parts[i]?'● ':'○ ')+n).join('　');document.querySelector('#action').textContent=c?c.label:'靠近物件操作';document.querySelector('#action').disabled=!c;document.querySelector('#action').classList.toggle('ready',!!c);document.querySelector('#journal-open').textContent=`圖鑑 ${journal.count} / 9`;}
function act(){if(!indoor)return;const result=interior.action();showObservation(result.message);if(result.complete)interior.setSmall(false);if(result.roomChange||result.complete){updateSize();document.querySelector('.subtitle').textContent=interior.room==='greenhouse'?'葉片、露珠與玻璃之間的小世界。':'尋找微小零件，或推開側門進入溫室。';}updateQuestHUD();}
document.querySelector('#action').onclick=act;document.querySelector('#restart').onclick=()=>{interior.quests.reset();interior.enter();updateSize();hudSignature='';updateQuestHUD();showObservation('客廳回到探索開始時的狀態。三個零件正等著被發現。');};addEventListener('keydown',e=>{if(indoor&&e.key.toLowerCase()==='f'&&!e.repeat)act();});

const ambience=createAmbience();
document.querySelector('#sound').onclick=async()=>{try{const r=await ambience.toggle();document.querySelector('#sound').textContent=r.on?'音效 開':'音效 關';document.querySelector('#sound').setAttribute('aria-pressed',String(r.on));if(r.error)showObservation(r.error);}catch{showObservation('音效暫時無法啟用，探索仍可繼續。');}};
function soundTick(now){ambience.setRoom(indoor?interior.room:'outside');ambience.update(now/1000);requestAnimationFrame(soundTick);}requestAnimationFrame(soundTick);
addEventListener('blur',()=>ambience.pause());addEventListener('focus',()=>ambience.resume());document.addEventListener('visibilitychange',()=>document.hidden?ambience.pause():ambience.resume());
function openJournal(){interior?.keys.clear();document.querySelector('#journal-panel').hidden=false;document.querySelector('#journal-grid').innerHTML=journal.entries.map(e=>`<article class="journal-card ${e.found?'found':''}"><div class="journal-art">${e.found?({bottle:'✧',button:'◎',spool:'▥',marble:'◉',fern:'❧',dew:'◌',flower:'✿',water:'≈',seed:'❦'}[e.id]):'?'}</div><small>${e.area}</small><h3>${e.found?e.title:'尚未發現'}</h3><p>${e.found?e.text:'走近物件觀察，留下你的發現。'}</p></article>`).join('');document.querySelector('#journal-title').textContent=`小小世界圖鑑 · ${journal.count} / 9`;document.querySelector('#journal-close').focus();}
document.querySelector('#journal-open').onclick=openJournal;document.querySelector('#journal-close').onclick=()=>{document.querySelector('#journal-panel').hidden=true;document.querySelector('#journal-open').focus();};addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#journal-panel').hidden=true;});
document.querySelector('#journal-open').textContent=`圖鑑 ${journal.count} / 9`;
document.querySelector('#door-guide').onclick=()=>{if(!indoor)return;if(interior.room==='greenhouse'){showObservation('溫室入口的木門通往客廳。靠近木門後，按「回到客廳」。');return;}interior.keys.clear();interior.position.set(3.9,interior.small?.2:1.62,2.85);interior.look((camera.rotation.y+Math.PI/2)/.004,(camera.rotation.x+.02)/.003);showObservation('側門上嵌著玻璃。靠近時，可以推門進入溫室。');updateQuestHUD();};
addEventListener('keydown',e=>{if(!document.querySelector('#journal-panel').hidden&&e.key!=='Escape'&&e.key!=='Tab'){e.preventDefault();e.stopImmediatePropagation();}},true);
